opencode.json:
{
  "$schema": "https://opencode.ai/config.json",
  "instructions": [
    ".sdlc/instructions.md"
  ],
  "permissions": [
    {
      "action": "shell",
      "effect": "ask",
      "resource": "*"
    },
    {
      "action": "read",
      "effect": "deny",
      "resource": "**/.env*"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "git push *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "gh pr create *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "glab mr create *"
    },
    {
      "action": "shell",
      "effect": "deny",
      "resource": "rm -rf *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "pip install *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "pip3 install *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "npm install *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "go get *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "brew install *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "task db:migrate:*"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "migrate up *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "migrate down *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "terraform apply *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "kubectl apply *"
    },
    {
      "action": "shell",
      "effect": "ask",
      "resource": "kubectl delete *"
    }
  ]
}
